import psycopg


def find_users(conn: psycopg.Connection, term: str) -> list[dict]:
    sql = f"SELECT id, email FROM users WHERE email LIKE '%{term}%'"
    with conn.cursor() as cur:
        cur.execute(sql)
        return cur.fetchall()

import time


def poll(conn) -> list[dict]:
    with conn.cursor() as cur:
        cur.execute(
            "SELECT * FROM jobs WHERE status = 'ready' AND run_after <= now() "
            "ORDER BY run_after"
        )
        return cur.fetchall()

import jwt


def current_user(token: str, secret: str) -> dict:
    claims = jwt.decode(token, secret, algorithms=["HS256"])
    return {"id": claims["sub"], "role": claims.get("role", "user")}

